1	// The executor's entry gate: identify the ONE dispatch this session was started
2	// for, and validate it in code BEFORE any model judgment (per-project-scheduling
3	// DESIGN §5.2). This is the CLI shell `validate-dispatch.mjs` was written to be
4	// driven by — it wires that pure core's `exists` / `isPackDeclared` / `loadTask`
5	// capabilities to this checkout and hands it the issue body.
6	//
7	// IT DOES NOT CLAIM. The claim protocol (read labels → swap ready → agent-running
8	// → post a claim comment → re-read, earliest claim wins) needs GitHub WRITES,
9	// which the executor session can only make through its MCP tools, so it stays
10	// agent-driven prose in executor.md. This shell only decides "is there a dispatch
11	// here, is it mine, and is it legal".
12	//
13	// TWO TRIGGER SOURCES, because the same `[REDACTED:env:CCR_TRIGGER_EVENT]` webhook reaches an
14	// executor session by two different transports and only one of them was ever
15	// read here:
16	//
17	//   1. GITHUB ACTIONS writes the whole webhook payload to disk at
18	//      `$GITHUB_EVENT_PATH` — `action`, `label.name` and the entire `issue`
19	//      object, `issue.number` and `issue.body` included. Payload plus local
20	//      checkout is everything the validation needs, in one shot.
21	//   2. CLAUDE CODE ON THE WEB (CCR) delivers the same trigger as environment
22	//      variables instead — `CCR_TRIGGER_SOURCE`, `CCR_TRIGGER_EVENT`,
23	//      `CCR_TRIGGER_REPO`, `CCR_TRIGGER_ISSUE_NUMBER` — and writes no payload
24	//      file at all. It NAMES the issue but carries neither the label that was
25	//      added nor the body, so it resolves in two shots: this shell reports
26	//      `needs-issue` with the number, the executor fetches that one issue over
27	//      MCP, saves the tool's raw JSON response verbatim to a file, and
28	//      re-invokes with `--issue-json` for the identical validation. The shell
29	//      extracts body, labels, and title from the response itself — the agent
30	//      pastes bytes, it never hand-extracts fields — and rejects a response
31	//      whose `number` is not the trigger's, so fetching the wrong issue is
32	//      caught in code. (`--issue-body-file` + `--issue-labels` remain as the
33	//      manual fallback should the fetch's response shape ever surprise.)
34	//
35	// Reading only source 1 is what made every CCR-run executor session miss its own
36	// trigger and select an issue by listing instead — the duplicate-execution bug
37	// re-entered through the front door. Observed live 2026-07-28: two sessions each
38	// selected dispatch #772 and claimed it one second apart.
39	//
40	// ZERO NETWORK, BY CONSTRUCTION — still. The executor session is MCP-only and
41	// carries no repo credential of its own, so anything reaching the GitHub REST API
42	// here would both fail to authenticate and trip the in-session-github-access
43	// rule. The CCR path does not change that: this shell never fetches the issue
44	// itself, it tells the EXECUTOR to fetch it over MCP and hand the bytes back.
45	//
46	// EXIT CODES ARE THE INTERFACE (see EXIT below). The executor branches on the
47	// number, so each verdict has its own code and its own documented next step:
48	//
49	//   0  valid       — a legal dispatch for this session's scope; go claim it.
50	//   10 invalid     — a forged or mangled dispatch. Comment the printed `reason`,
51	//                    remove the ready label, add `needs-human`, end the session.
52	//                    It never runs.
53	//   11 not-mine    — the trigger label is the OTHER executor's ready label, is no
54	//                    ready label at all, or the issue no longer carries one (a
55	//                    dispatch another session has already claimed). Stop. Change
56	//                    nothing, comment nothing.
57	//   13 needs-issue — a CCR trigger named the issue but carries no body/labels.
58	//                    Fetch THAT issue over MCP and re-invoke with them.
59	//   12 no-trigger  — NO source names an issue. STOP THE SESSION. There is no
60	//                    fallback: never select a dispatch by listing (see below).
61	//   2  usage       — bad invocation (an unknown scope argument, an unreadable
62	//                    `--issue-body-file`).
63	//   1  internal    — an unexpected fault in this shell.
64	//
65	// THERE IS NO FALLBACK, BY DESIGN. Exit 12 used to send the executor off to list
66	// the open dispatches and take the oldest. That is precisely the
67	// N-sessions-racing-over-N-issues failure the one-session-one-issue rule exists to
68	// prevent, reached from the other direction: one scheduler run files every due
69	// dispatch seconds apart, so every session that cannot name its own trigger builds
70	// the SAME work list and races over it. A session that does not know its issue
71	// must run nothing — the scheduler re-arms an unrun dispatch on its next hourly
72	// pass, so stopping costs a delay while guessing costs duplicated work.
73	//
74	// Usage: `node <engine>/scheduler/resolve-dispatch.mjs [self|fleet]`
75	//                `[--issue-json <path> | --issue-body-file <path> --issue-labels <csv>]`
76	// The positional argument is THIS SESSION's scope — which of the two executor
77	// routines is running. It defaults to `self`, which is every ordinary project's
78	// executor; the FLEET routine must pass `fleet` explicitly, and a fleet payload
79	// arriving at a session that did not is reported as not-mine with that stated
80	// plainly. The flags carry what a CCR trigger cannot, and are ignored on the
81	// Actions path (whose payload already has everything).
82	
83	import { existsSync, readFileSync } from 'node:fs';
84	import { dirname, join, sep } from 'node:path';
85	import { fileURLToPath, pathToFileURL } from 'node:url';
86	import { DISPATCH_PATH_RE, dispatchFirstLine, validateDispatchBody } from './validate-dispatch.mjs';
87	import { parseDispatchTitle, readyLabelForScope } from './dispatch.mjs';
88	import { SESSION_SCOPES } from './task-contract.mjs';
89	import { SHARED_SUBDIR } from '../pack_loader/pack-registry.mjs';
90	
91	export const EXIT = {
92	  ok: 0,
93	  internal: 1,
94	  usage: 2,
95	  invalid: 10,
96	  notMine: 11,
97	  noTrigger: 12,
98	  needsIssue: 13,
99	};
100	
101	// The executor scope a ready label implies — the exact inverse of the mapping the
102	// SCHEDULER files a dispatch under (`readyLabelForScope`), derived from it rather
103	// than restated, so the two can never drift. `null` = not a ready label at all.
104	export const scopeForLabel = (label) =>
105	  SESSION_SCOPES.find((scope) => readyLabelForScope(scope) === label) ?? null;
106	
107	// Which checkout do the task paths in a dispatch body resolve against? Answered
108	// from where THIS engine copy is mounted, not from cwd — a consumer runs the
109	// vendored engine at `<root>/.claudinite/shared/engine/scheduler/`, the canon
110	// repo runs its own at `<root>/engine/scheduler/`. Deriving it from the module's
111	// own location means whichever copy the executor invoked resolves against that
112	// copy's own repo, with nothing to pass — and nothing for executor.md to explain.
113	const MOUNT_SUFFIX = sep + SHARED_SUBDIR;
114	export function repoRootFrom(moduleUrl) {
115	  const home = dirname(dirname(dirname(fileURLToPath(moduleUrl)))); // <home>/engine/scheduler/<this file>
116	  return home.endsWith(MOUNT_SUFFIX) ? home.slice(0, -MOUNT_SUFFIX.length) : home;
117	}
118	
119	// Read the webhook payload the label event was started with. Every way of not
120	// having one collapses to a single `{ error }` — unset, unreadable, unparsable —
121	// because the caller's response to all of them is the same: try the other
122	// trigger source, and stop the session if that names no issue either.
123	export function readEventPayload(env = process.env, read = (p) => readFileSync(p, 'utf8')) {
124	  const path = env.GITHUB_EVENT_PATH;
125	  if (!path) return { error: 'GITHUB_EVENT_PATH is not set — this session has no event payload on disk' };
126	  let raw;
127	  try {
128	    raw = read(path);
129	  } catch (e) {
130	    return { error: `GITHUB_EVENT_PATH points at ${path}, which is unreadable: ${e.message}` };
131	  }
132	  let event;
133	  try {
134	    event = JSON.parse(raw);
135	  } catch (e) {
136	    return { error: `the event payload at ${path} is not valid JSON: ${e.message}` };
137	  }
138	  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
139	    return { error: `the event payload at ${path} is not an event object` };
140	  }
141	  return { event };
142	}
143	
144	// The three facts a dispatch trigger must carry. Anything short of all three
145	// means the payload cannot name this session's issue — not a rejection of a
146	// dispatch, just this source failing to identify one; the caller tries the other
147	// source before giving up.
148	export function triggerFromEvent(event) {
149	  const action = event.action;
150	  const label = event.label?.name;
151	  const number = event.issue?.number;
152	  if (action !== 'labeled') return { error: `the event payload is a "${action}" event, not a label event — it names no dispatch` };
153	  if (typeof label !== 'string' || label === '') return { error: 'the label event carries no label.name' };
154	  if (!Number.isInteger(number)) return { error: 'the label event carries no issue.number' };
155	  return { trigger: { source: 'payload', label, number, body: event.issue?.body ?? '', title: event.issue?.title ?? '' } };
156	}
157	
158	// The CCR trigger: same webhook, delivered as environment variables by Claude
159	// Code on the web, which writes no payload file. It names the issue and nothing
160	// else — no `label.name`, no `issue.body` — so the trigger it yields is
161	// deliberately PARTIAL, and `main` turns that into the two-shot `needs-issue`
162	// handshake rather than guessing either missing field.
163	export function triggerFromCcrEnv(env = process.env) {
164	  const source = env.CCR_TRIGGER_SOURCE;
165	  const event = env.CCR_TRIGGER_EVENT;
166	  const raw = env.CCR_TRIGGER_ISSUE_NUMBER;
167	  if (!source && !event && !raw) return { error: 'no CCR_TRIGGER_* variables are set either — this session carries no CCR trigger' };
168	  if (source !== 'github') return { error: `CCR_TRIGGER_SOURCE is ${JSON.stringify(source ?? null)}, not "github" — this session was not started by a GitHub event` };
169	  if (event !== '[REDACTED:env:CCR_TRIGGER_EVENT]') return { error: `CCR_TRIGGER_EVENT is ${JSON.stringify(event ?? null)}, not "[REDACTED:env:CCR_TRIGGER_EVENT]" — it names no dispatch` };
170	  const number = Number(raw);
171	  if (!raw || !Number.isInteger(number) || number <= 0) return { error: `CCR_TRIGGER_ISSUE_NUMBER is ${JSON.stringify(raw ?? null)}, which is not an issue number` };
172	  return { trigger: { source: 'ccr', number, repo: env.CCR_TRIGGER_REPO ?? '' } };
173	}
174	
175	// Identify this session's ONE dispatch from whichever transport carried it.
176	// Order is preference, not precedence-by-truth: the Actions payload is tried
177	// first only because it answers in one shot, and a session that somehow has both
178	// gets the same issue from either. Every failure of both sources is collected
179	// into one reason, because the executor prints it and then stops.
180	export function resolveTrigger(env = process.env, read) {
181	  const reasons = [];
182	  const { event, error: payloadError } = readEventPayload(env, read);
183	  if (payloadError) reasons.push(payloadError);
184	  else {
185	    const { trigger, error } = triggerFromEvent(event);
186	    if (trigger) return { trigger };
187	    reasons.push(error);
188	  }
189	  const { trigger: ccr, error: ccrError } = triggerFromCcrEnv(env);
190	  if (ccr) return { trigger: ccr };
191	  reasons.push(ccrError);
192	  return { error: reasons.join('; ') };
193	}
194	
195	// `[scope] [--flag value|--flag=value]`. Kept deliberately tiny — the shell takes
196	// one positional and two flags, and a dependency-free parser is less surface than
197	// the alternative.
198	export function parseArgs(argv) {
199	  const positional = [];
200	  const flags = {};
201	  for (let i = 0; i < argv.length; i++) {
202	    const arg = argv[i];
203	    if (!arg.startsWith('--')) { positional.push(arg); continue; }
204	    const eq = arg.indexOf('=');
205	    if (eq !== -1) flags[arg.slice(2, eq)] = arg.slice(eq + 1);
206	    else flags[arg.slice(2)] = argv[++i] ?? '';
207	  }
208	  return { positional, flags };
209	}
210	
211	// Which of the issue's CURRENT labels is a ready label? On the CCR path this
212	// stands in for the `label.name` the trigger never carried — and it is strictly
213	// more informative than the event's: a dispatch another session already claimed
214	// no longer carries a ready label at all, so this catches the lost race here at
215	// step 1 rather than at the claim.
216	export function readyLabelAmong(labels) {
217	  const ready = labels.filter((l) => scopeForLabel(l) !== null);
218	  if (ready.length === 0) return { error: `it carries no ready label (it has: ${labels.join(', ') || 'none'}) — its dispatch has already been claimed or converged by another session` };
219	  if (ready.length > 1) return { error: `it carries more than one ready label (${ready.join(', ')}), so which executor owns it is ambiguous` };
220	  return { label: ready[0] };
221	}
222	
223	// The CCR handshake's payload: the raw issue-fetch response, saved verbatim.
224	// The whole point is that the executor pastes bytes instead of hand-extracting
225	// fields — a body threaded through the shell mangles quoting, a hand-assembled
226	// labels CSV drops one. Accepts both label shapes (the MCP tools return plain
227	// strings, the REST API returns { name } objects), and surfaces `number` so the
228	// caller can assert the agent fetched the issue the trigger actually names.
229	export function parseIssueJson(raw) {
230	  let issue;
231	  try {
232	    issue = JSON.parse(raw);
233	  } catch (e) {
234	    return { error: `not valid JSON: ${e.message}` };
235	  }
236	  if (issue === null || typeof issue !== 'object' || Array.isArray(issue)) {
237	    return { error: 'not an issue object' };
238	  }
239	  const labels = (Array.isArray(issue.labels) ? issue.labels : [])
240	    .map((l) => (typeof l === 'string' ? l : l?.name))
241	    .filter((l) => typeof l === 'string' && l !== '');
242	  return { issue: {
243	    number: Number.isInteger(issue.number) ? issue.number : null,
244	    body: typeof issue.body === 'string' ? issue.body : '',
245	    labels,
246	    title: typeof issue.title === 'string' ? issue.title : '',
247	  } };
248	}
249	
250	// The block the executor reads. `key: value` lines, one fact per line: an agent
251	// quoting a field back must not have to parse prose, and a reader diffing two
252	// runs must see exactly what changed.
253	const block = (fields) => Object.entries(fields).map(([k, v]) => `${k}: ${v}`).join('\n');
254	
255	function done(code, fields, advice) {
256	  console.log(block(fields));
257	  if (advice) console.error(`resolve-dispatch: ${advice}`);
258	  process.exit(code);
259	}
260	
261	async function main() {
262	  const { positional, flags } = parseArgs(process.argv.slice(2));
263	  const scopeGiven = positional.length > 0;
264	  const scope = positional[0] ?? 'self';
265	  if (!SESSION_SCOPES.includes(scope)) {
266	    console.error(`resolve-dispatch: unknown scope "${scope}" — usage: node resolve-dispatch.mjs [${SESSION_SCOPES.join('|')}] [--issue-json <path> | --issue-body-file <path> --issue-labels <csv>]`);
267	    process.exit(EXIT.usage);
268	  }
269	
270	  const { trigger, error: triggerError } = resolveTrigger();
271	  if (triggerError) {
272	    done(EXIT.noTrigger, { dispatch: 'no-trigger', scope, reason: triggerError },
273	      `${triggerError}. No trigger source names an issue, so this session cannot know which dispatch it was started for. STOP: run nothing, change nothing, comment nothing, end the session. There is NO fallback — never pick an issue by listing ${readyLabelForScope(scope)}; every dispatch in that list already has its own session, and the scheduler re-arms an unrun one on its next hourly pass.`);
274	  }
275	
276	  let { label, number, body } = trigger;
277	  let title = trigger.title ?? '';
278	
279	  // The CCR handshake: the trigger named the issue, the executor fetched it over
280	  // MCP, and hands back here — as the raw response, or the manual two-flag
281	  // fallback — the fields the environment could not carry.
282	  if (trigger.source === 'ccr') {
283	    const jsonFile = flags['issue-json'];
284	    const bodyFile = flags['issue-body-file'];
285	    const labelsCsv = flags['issue-labels'];
286	    let labels;
287	    if (jsonFile !== undefined) {
288	      let raw;
289	      try {
290	        raw = readFileSync(jsonFile, 'utf8');
291	      } catch (e) {
292	        console.error(`resolve-dispatch: --issue-json ${jsonFile} is unreadable: ${e.message}`);
293	        process.exit(EXIT.usage);
294	      }
295	      const { issue, error } = parseIssueJson(raw);
296	      if (error) {
297	        console.error(`resolve-dispatch: --issue-json ${jsonFile} is ${error}`);
298	        process.exit(EXIT.usage);
299	      }
300	      if (issue.number !== null && issue.number !== number) {
301	        console.error(`resolve-dispatch: --issue-json carries issue #${issue.number}, but this session's trigger names #${number} — that is the wrong issue. Fetch #${number} alone and re-run.`);
302	        process.exit(EXIT.usage);
303	      }
304	      ({ body, title } = issue);
305	      labels = issue.labels;
306	    } else if (bodyFile !== undefined && labelsCsv !== undefined) {
307	      try {
308	        body = readFileSync(bodyFile, 'utf8');
309	      } catch (e) {
310	        console.error(`resolve-dispatch: --issue-body-file ${bodyFile} is unreadable: ${e.message}`);
311	        process.exit(EXIT.usage);
312	      }
313	      labels = labelsCsv.split(',').map((l) => l.trim()).filter(Boolean);
314	    } else {
315	      done(EXIT.needsIssue, { dispatch: 'needs-issue', issue: number, scope, source: 'ccr', repo: trigger.repo || '(unset)' },
316	        `the CCR trigger names issue #${number} but carries neither its body nor its labels. Fetch ISSUE #${number} ALONE over MCP (the issue-get tool), save the tool's raw JSON response verbatim to a file, then re-run: node <engine>/scheduler/resolve-dispatch.mjs ${scope} --issue-json <path>. Do not list, select, or touch any other issue.`);
317	    }
318	    const { label: ready, error: labelError } = readyLabelAmong(labels);
319	    if (labelError) {
320	      done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, labels: labels.join('|') || '(none)' },
321	        `issue #${number}: ${labelError}. Stop: change nothing, comment nothing.`);
322	    }
323	    label = ready;
324	  }
325	
326	  const labelScope = scopeForLabel(label);
327	  if (labelScope === null) {
328	    done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, label },
329	      `issue #${number} was labeled "${label}", which is not a ready label — this is not an executor dispatch. Stop: change nothing, comment nothing.`);
330	  }
331	  if (labelScope !== scope) {
332	    done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, label, labelScope },
333	      `issue #${number} is labeled "${label}", a ${labelScope}-scoped dispatch, but this session's scope is "${scope}"${scopeGiven ? '' : ' (the default — pass "fleet" if this IS the fleet executor)'}. It is the other executor's to run and it already has a session. Stop: change nothing, comment nothing.`);
334	  }
335	
336	  // The checkout the dispatch's task path must resolve in. `exists` reads the
337	  // working tree; in an executor session that IS HEAD (a fresh checkout, nothing
338	  // written yet), which is what validate-dispatch means by "exists at HEAD".
339	  const root = process.env.CLAUDINITE_REPO_ROOT || repoRootFrom(import.meta.url);
340	  const { loadConfig } = await import('../checks/helpers/repo-context.mjs');
341	  const declared = new Set(loadConfig(root).packs);
342	
343	  // `loadTask` is SYNCHRONOUS by design — it keeps validate-dispatch's core pure
344	  // and sync-testable — but importing an .mjs is not, so the shell prefetches the
345	  // module here and the capability just replays the result (or rethrows the parse
346	  // failure, which is exactly what the core wants to report).
347	  const firstLine = dispatchFirstLine(body);
348	  const mjsRelative = firstLine.replace(/task\.md$/, 'task.mjs');
349	  let loaded = null;
350	  let loadError = null;
351	  if (DISPATCH_PATH_RE.test(firstLine) && existsSync(join(root, mjsRelative))) {
352	    try {
353	      loaded = (await import(pathToFileURL(join(root, mjsRelative)).href)).default;
354	    } catch (e) {
355	      loadError = e;
356	    }
357	  }
358	
359	  const verdict = validateDispatchBody(body, {
360	    exists: (p) => existsSync(join(root, p)),
361	    isPackDeclared: (id) => declared.has(id),
362	    loadTask: () => { if (loadError) throw loadError; return loaded; },
363	  });
364	
365	  if (!verdict.ok) {
366	    done(EXIT.invalid, { dispatch: 'invalid', issue: number, scope, label, reason: verdict.reason },
367	      `issue #${number} is not a valid dispatch: ${verdict.reason}. It must not run — comment naming what failed, remove the "${label}" label, add "needs-human", and end the session.`);
368	  }
369	
370	  // `brief` is the one line the executor quotes prominently in chat before it
371	  // acts, so a human skimming the session sees at a glance which task ran and
372	  // under what parameters. The slot comes from the dispatch title when the
373	  // trigger carried one (the Actions payload and --issue-json both do; the
374	  // manual two-flag fallback does not).
375	  const slot = parseDispatchTitle(title)?.slotId ?? null;
376	  done(EXIT.ok, {
377	    dispatch: 'valid',
378	    brief: `Task: ${verdict.pack}/${verdict.task}${slot ? ` (slot ${slot})` : ''} — issue #${number}, model ${verdict.resolvedModel}, outcome ceiling ${verdict.outcome}, timeout ${verdict.executionTimeout ?? 'none'}s`,
379	    issue: number,
380	    scope,
381	    label,
382	    source: trigger.source,
383	    taskPath: verdict.taskPath,
384	    pack: verdict.pack,
385	    task: verdict.task,
386	    slot: slot ?? 'unknown',
387	    model: verdict.model,
388	    resolvedModel: verdict.resolvedModel,
389	    outcome: verdict.outcome,
390	    executionTimeout: verdict.executionTimeout ?? 'none',
391	  });
392	}
393	
394	// Run only when invoked directly (the executor's `node resolve-dispatch.mjs`),
395	// never on import — the exported helpers above are unit-testable without it.
396	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
397	  main().catch((e) => { console.error(`resolve-dispatch: ${e.stack || e}`); process.exit(EXIT.internal); });
398	}
399

